) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_amelia_coupons_to_services`;
CREATE TABLE `SERVMASK_PREFIX_amelia_coupons_to_services` (
