INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (1,'customer_appointment_approved',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Approved','Dear <strong>%customer_full_name%</strong>,<br><br>You have successfully scheduled\n                     <strong>%service_name%</strong> appointment with <strong>%employee_full_name%</strong>. We are \n                     waiting you at <strong>%location_address% </strong>on <strong>%appointment_date_time%</strong>.\n                     <br><br>Thank you for choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (2,'customer_appointment_pending',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Pending','Dear <strong>%customer_full_name%</strong>,<br><br>The <strong>%service_name%</strong> appointment \n                     with <strong>%employee_full_name%</strong> at <strong>%location_address%</strong>, scheduled for\n                     <strong>%appointment_date_time%</strong> is waiting for a confirmation.<br><br>Thank you for \n                     choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
