INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (33,'customer_event_next_day_reminder',NULL,'enabled','email','event','17:00:00',NULL,NULL,'customer','%event_name% Event Reminder','Dear <strong>%customer_full_name%</strong>,<br><br>We would like to remind you that you have\n                     <strong>%event_name%</strong> event tomorrow at <strong>%event_start_date_time%</strong>.\n                     We are waiting for you at <strong>%event_location%</strong>.<br><br>Thank you for\n                     choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (34,'customer_event_follow_up',NULL,'enabled','email','event',NULL,NULL,1800,'customer','%event_name% Event Follow Up','Dear <strong>%customer_full_name%</strong>,<br><br>Thank you once again for choosing our company.\n                     We hope you were satisfied with your <strong>%event_name%</strong>.<br><br>We look forward to\n                     seeing you again soon,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (35,'provider_event_approved',NULL,'enabled','email','event',NULL,NULL,NULL,'provider','%event_name% Event Booked','Hi <strong>%employee_full_name%</strong>,<br><br>You have one confirmed\n                     <strong>%event_name%</strong> Event at <strong>%event_location%</strong> on\n                     <strong>%event_start_date_time%</strong>. The event\n                     is added to your schedule.<br><br>Thank you,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (36,'provider_event_rejected',NULL,'enabled','email','event',NULL,NULL,NULL,'provider','%event_name% Event Canceled By Admin','Hi <strong>%employee_full_name%</strong>,<br><br>Your <strong>%event_name%</strong> event\n                     at <strong>%event_location%</strong>, scheduled for <strong>%event_start_date_time%</strong>\n                     has been canceled.<br><br>Thank you,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (37,'provider_event_canceled',NULL,'enabled','email','event',NULL,NULL,NULL,'provider','%event_name% Event Canceled By Customer','Hi <strong>%employee_full_name%</strong>,<br><br>Your <strong>%event_name%</strong> event,\n                     scheduled on <strong>%event_start_date_time%</strong>, at <strong>%event_location%</strong> has been\n                     canceled.<br><br>Thank you,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (38,'provider_event_rescheduled',NULL,'enabled','email','event',NULL,NULL,NULL,'provider','%event_name% Event Rescheduled','Hi <strong>%employee_full_name%</strong>,<br><br>The details for your\n                     <strong>%event_name%</strong> event at <strong>%event_location%</strong> has been changed.\n                     The event is now set for <strong>%event_start_date_time%</strong>.\n                     <br><br>Thank you,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (39,'provider_event_next_day_reminder',NULL,'enabled','email','event','17:00:00',NULL,NULL,'provider','%event_name% Event Reminder','Dear <strong>%employee_full_name%</strong>,<br><br>We would like to remind you that you have \n                     <strong>%event_name%</strong> event at <strong>%event_start_date_time%</strong>\n                     at <strong>%event_location%</strong>.<br><br>Thank you, \n                     <br><strong>%company_name%</strong>',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (40,'customer_event_approved',NULL,'enabled','sms','event',NULL,NULL,NULL,'customer','NULL','Dear %customer_full_name%,\n\nYou have successfully scheduled %event_name% event. We are waiting for you at %event_location% on %event_start_date_time%.\n\nThank you for choosing our company,\n%company_name%',NULL,0,NULL,NULL);
INSERT INTO `SERVMASK_PREFIX_amelia_notifications` VALUES (41,'customer_event_rejected',NULL,'enabled','sms','event',NULL,NULL,NULL,'customer','NULL','Dear %customer_full_name%,\n\nYour %event_name% event, scheduled on %event_start_date_time% at %event_location% has been cancelled.\n\nThank you for choosing our company,\n%company_name%',NULL,0,NULL,NULL);
